/* cppi::3bdd766afcc72bb8904c07017abcff85facf159269740da39fadd7a5f35d6197 */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-20' and business_date <= date '2025-06-20' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

/* cppi::9ceaba166abb0c0ea3f60a2244f6182ec5aeccf8ff6183a020479da61d11fffb */
select business_date as date_, security_id, 'SP500_20' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-20' and business_date <= date '2025-06-20' and weight_ndo>0 and id_cppib_index = 'SP500_20_GR_USD_0_0' and security_id is not null

