/* cppi::d83f7ae2fb9d1104ddb0e0e899b5f61948280d107138356afa208f482f5be375 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2024-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-03-03'
    ) a
where arrival_time = max_publish

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::9383f99a14cae588853d6941a4e63c6fb67c6ed90bd0ca4009faeb37e19f9dd8 */
SELECT COUNT(*) FROM ( 
    select currency_name, currency_code 
    from reference.reference_currency_codes
    where business_date = ( select max( business_date ) from reference.reference_currency_codes )
 ) t

/* cppi::eceb8685ebc4d4f8b3b34f327842569d7a336c57a1b08eb1f9203e42399d6dba */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-01-02'
    ) a
where last_publish = max_publish

